"use strict";
// Run manager for POST /v2/run: queueing, spawning `claude -p` in stream-json mode,
// normalizing events, per-run replay buffer, SSE fan-out, abort.

const { spawn } = require("child_process");
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const { Normalizer } = require("./normalizer");

const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
const RUN_ID_RE = /^[A-Za-z0-9._:-]{1,128}$/;
const SESSION_ID_RE = /^[A-Za-z0-9._-]{1,128}$/;
const MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
const MODES = new Set(["auto", "edit", "plan", "ask"]);
const THINKING = { off: "0", normal: "8000", max: "32000" };
const EFFORTS = new Set(["low", "medium", "high", "xhigh", "max"]);
const AGENT_NAME_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
const AGENT_MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
const TOOL_NAME_RE = /^[A-Za-z0-9_*:().\- ]{1,200}$/;
const AGENTS_INLINE_MAX = 32 * 1024; // larger --agents JSON goes through a temp file
// --autocompact takes the auto-compact *window* (100k-1M); compaction fires at window - 13k
// (CLI: threshold = min(window - 13000, window * PCT_OVERRIDE/100)).
const AUTOCOMPACT_MIN_WINDOW = 100_000;
const AUTOCOMPACT_MAX_WINDOW = 1_000_000;
const AUTOCOMPACT_BUFFER = 13_000;

const EDIT_TOOLS = ["Read", "Edit", "Write", "Glob", "Grep", "Bash", "WebFetch", "WebSearch", "TodoWrite", "NotebookEdit", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList"];
const ASK_TOOLS = ["Read", "Glob", "Grep", "WebFetch", "WebSearch", "TodoWrite", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList"];

const TERMINAL = new Set(["done", "error", "aborted"]);

function isInside(child, parent) {
  const rel = path.relative(parent, child);
  return rel === "" || (!!rel && !rel.startsWith("..") && !path.isAbsolute(rel));
}

/**
 * Build CLI args for a v2 run. `features` comes from parsing `claude --help`.
 */
function buildRunArgs(opts, features = {}, config = {}) {
  const args = ["-p", "--output-format", "stream-json", "--verbose", "--include-partial-messages"];
  if (features.permissionPrompts !== false) args.push("--permission-prompts", "none");
  if (opts.model) args.push("--model", opts.model);
  if (opts.sessionId) args.push("--resume", opts.sessionId);
  if (opts.maxTurns) args.push("--max-turns", String(opts.maxTurns));
  // Effort drives thinking depth and verbosity: keep simple requests cheap.
  const EFFORT = { off: "low", normal: "medium", max: "high" };
  const effort = opts.effort || (features.effort !== false ? EFFORT[opts.thinking || "normal"] : null);
  if (effort) args.push("--effort", effort);
  // Newer CLIs hide thinking text unless asked; summarized display streams readable thinking deltas.
  if (opts.thinking !== "off" && config.thinkingDisplay) args.push("--thinking-display", config.thinkingDisplay);
  if (opts.appendSystemPrompt) args.push("--append-system-prompt", opts.appendSystemPrompt);
  if (config.uploadsDir) args.push("--add-dir", config.uploadsDir);
  const ac = autocompactPlan(opts.autocompactTokens);
  if (ac && features.autocompact !== false) args.push("--autocompact", String(ac.window));
  const hasAgents = !!(opts.agents && Object.keys(opts.agents).length);
  if (hasAgents) args.push("--agents", opts.agentsFile || JSON.stringify(opts.agents));
  if (opts.agent) args.push("--agent", opts.agent);
  if (features.forwardSubagentText && config.forwardSubagentText !== false) args.push("--forward-subagent-text");

  const modes = features.permissionModes || null; // null = unknown, assume all
  const has = (m) => !modes || modes.includes(m);
  switch (opts.mode || "auto") {
    case "auto": {
      const wanted = config.autoPermissionMode || "bypassPermissions";
      args.push("--permission-mode", has(wanted) ? wanted : "bypassPermissions");
      break;
    }
    case "edit":
      // Custom subagents are only useful in edit mode if the Agent tool is pre-approved.
      args.push("--permission-mode", "acceptEdits", "--allowedTools", ...EDIT_TOOLS, ...(hasAgents ? ["Agent"] : []));
      break;
    case "plan":
      args.push("--permission-mode", "plan");
      break;
    case "ask":
      if (has("dontAsk")) args.push("--permission-mode", "dontAsk");
      args.push("--tools", ASK_TOOLS.join(","), "--allowedTools", ...ASK_TOOLS);
      break;
  }
  args.push("--", opts.fullPrompt ?? opts.prompt);
  return args;
}

/**
 * Map a desired auto-compact *threshold* (tokens of context at which compaction fires) to CLI settings.
 * Returns null for "CLI default" (0 / null). Thresholds below 87k use the minimum window (100k) plus
 * CLAUDE_AUTOCOMPACT_PCT_OVERRIDE (percent of the window).
 */
function autocompactPlan(tokens) {
  if (!tokens) return null;
  const want = tokens + AUTOCOMPACT_BUFFER;
  if (want >= AUTOCOMPACT_MIN_WINDOW) return { window: Math.min(AUTOCOMPACT_MAX_WINDOW, want), pct: null };
  return { window: AUTOCOMPACT_MIN_WINDOW, pct: Math.round((tokens / AUTOCOMPACT_MIN_WINDOW) * 1000) / 10 };
}

function validateAgents(raw) {
  if (raw == null) return { agents: null };
  if (typeof raw !== "object" || Array.isArray(raw)) return { error: "Invalid agents (object expected)" };
  const names = Object.keys(raw);
  if (names.length > 100) return { error: "Too many agents" };
  const out = {};
  for (const name of names) {
    const a = raw[name];
    if (!AGENT_NAME_RE.test(name)) return { error: `Invalid agent name: ${name}` };
    if (!a || typeof a !== "object") return { error: `Invalid agent: ${name}` };
    if (typeof a.description !== "string" || !a.description.trim() || a.description.length > 4000) return { error: `Agent ${name}: invalid description` };
    if (typeof a.prompt !== "string" || !a.prompt.trim() || a.prompt.length > 100_000) return { error: `Agent ${name}: invalid prompt` };
    const def = { description: a.description, prompt: a.prompt };
    if (a.tools != null) {
      if (!Array.isArray(a.tools) || a.tools.length > 100 || !a.tools.every((t) => typeof t === "string" && TOOL_NAME_RE.test(t)))
        return { error: `Agent ${name}: invalid tools` };
      def.tools = a.tools;
    }
    if (a.model != null && a.model !== "") {
      if (typeof a.model !== "string" || !AGENT_MODEL_RE.test(a.model)) return { error: `Agent ${name}: invalid model` };
      def.model = a.model;
    }
    out[name] = def;
  }
  return { agents: out };
}

function buildPrompt(prompt, attachments) {
  let out = prompt || "";
  if (attachments && attachments.length) {
    const lines = attachments.map((a) => `[Attached file: ${a} — use Read tool]`);
    out = out ? `${out}\n\n${lines.join("\n")}` : lines.join("\n");
  }
  return out;
}

function buildChildEnv(baseEnv, opts) {
  const env = { ...baseEnv };
  delete env.CLAUDEBOX_API_KEY;
  delete env.PORT; // never leak the API server's PORT to Claude's shell
  if (opts.authToken) {
    if (opts.authToken.startsWith("sk-ant-api")) {
      env.ANTHROPIC_API_KEY = opts.authToken;
      delete env.CLAUDE_CODE_OAUTH_TOKEN;
    } else {
      env.CLAUDE_CODE_OAUTH_TOKEN = opts.authToken;
      delete env.ANTHROPIC_API_KEY;
    }
  }
  if (opts.thinking && THINKING[opts.thinking] !== undefined) env.MAX_THINKING_TOKENS = THINKING[opts.thinking];
  const ac = autocompactPlan(opts.autocompactTokens);
  if (ac && ac.pct != null) env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE = String(ac.pct);
  else delete env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE;
  if (opts.previewPort) {
    env.PORT = String(opts.previewPort);
    env.HOST = "0.0.0.0";
    env.BASE_PATH = `/preview/${opts.projectSlug}/`;
    env.NXEON_PREVIEW_PORT = String(opts.previewPort);
  }
  env.NXEON_PROJECT_SLUG = opts.projectSlug;
  env.NXEON_RUN_ID = opts.runId;
  return env;
}

class RunManager {
  constructor(config) {
    this.config = {
      claudeBin: "claude",
      projectsDir: "/workspace/projects",
      uploadsDir: "/workspace/uploads",
      maxConcurrent: 4,
      retentionMs: 30 * 60 * 1000,
      maxEventsPerRun: 50000,
      killGraceMs: 4000,
      heartbeatMs: 15000,
      previewPortMin: 4100,
      previewPortMax: 4199,
      autoPermissionMode: "bypassPermissions",
      thinkingDisplay: "summarized",
      forwardSubagentText: true,
      log: () => {},
      features: () => ({}),
      env: process.env,
      ...config,
    };
    this.runs = new Map();
    this.queue = [];
    this.running = 0;
    this._gc = setInterval(() => this.gc(), 60 * 1000);
    this._gc.unref();
  }

  close() {
    clearInterval(this._gc);
    for (const run of this.runs.values()) {
      for (const sub of run.subscribers) clearInterval(sub.hb);
      if (run.status === "running") this._kill(run, "SIGKILL");
    }
  }

  /** Validate a /v2/run body. Returns {opts} or {error}. */
  validate(body) {
    const c = this.config;
    if (!body || typeof body !== "object") return { error: "Body must be a JSON object" };
    const runId = body.runId == null ? crypto.randomUUID() : body.runId;
    if (typeof runId !== "string" || !RUN_ID_RE.test(runId)) return { error: "Invalid runId" };
    if (typeof body.prompt !== "string") return { error: "Missing 'prompt' (string)" };
    if (body.prompt.length > 1_000_000) return { error: "Prompt too large" };
    if (typeof body.projectSlug !== "string" || !SLUG_RE.test(body.projectSlug))
      return { error: "Invalid projectSlug (must match ^[a-z0-9][a-z0-9-]{0,47}$)" };
    const sessionId = body.sessionId == null || body.sessionId === "" ? null : body.sessionId;
    if (sessionId !== null && (typeof sessionId !== "string" || !SESSION_ID_RE.test(sessionId))) return { error: "Invalid sessionId" };
    const model = body.model == null || body.model === "" ? null : body.model;
    if (model !== null && (typeof model !== "string" || !MODEL_RE.test(model))) return { error: "Invalid model" };
    const mode = body.mode == null ? "auto" : body.mode;
    if (!MODES.has(mode)) return { error: "Invalid mode (auto|edit|plan|ask)" };
    const thinking = body.thinking == null ? null : body.thinking;
    if (thinking !== null && THINKING[thinking] === undefined) return { error: "Invalid thinking (off|normal|max)" };
    const effort = body.effort == null ? null : body.effort;
    if (effort !== null && !EFFORTS.has(effort)) return { error: "Invalid effort" };
    let maxTurns = null;
    if (body.maxTurns != null) {
      maxTurns = Number(body.maxTurns);
      if (!Number.isInteger(maxTurns) || maxTurns < 1 || maxTurns > 1000) return { error: "Invalid maxTurns" };
    }
    let previewPort = null;
    if (body.previewPort != null) {
      previewPort = Number(body.previewPort);
      if (!Number.isInteger(previewPort) || previewPort < c.previewPortMin || previewPort > c.previewPortMax)
        return { error: `Invalid previewPort (${c.previewPortMin}-${c.previewPortMax})` };
    }
    const appendSystemPrompt = body.appendSystemPrompt == null ? null : body.appendSystemPrompt;
    if (appendSystemPrompt !== null && (typeof appendSystemPrompt !== "string" || appendSystemPrompt.length > 200_000))
      return { error: "Invalid appendSystemPrompt" };
    const authToken = body.authToken == null || body.authToken === "" ? null : body.authToken;
    if (authToken !== null && (typeof authToken !== "string" || authToken.length > 8192 || /[\r\n\0]/.test(authToken)))
      return { error: "Invalid authToken" };

    let autocompactTokens = null;
    if (body.autocompactTokens != null && body.autocompactTokens !== 0) {
      autocompactTokens = Number(body.autocompactTokens);
      if (!Number.isInteger(autocompactTokens) || autocompactTokens < 10_000 || autocompactTokens > AUTOCOMPACT_MAX_WINDOW - AUTOCOMPACT_BUFFER)
        return { error: "Invalid autocompactTokens (0 or 10000-987000)" };
    }
    const va = validateAgents(body.agents);
    if (va.error) return { error: va.error };
    const agents = va.agents && Object.keys(va.agents).length ? va.agents : null;
    const agent = body.agent == null || body.agent === "" ? null : body.agent;
    if (agent !== null && (typeof agent !== "string" || !AGENT_NAME_RE.test(agent))) return { error: "Invalid agent" };
    if (agent !== null && agents && !agents[agent]) return { error: `Lead agent "${agent}" is not in agents` };

    const cwd = path.join(c.projectsDir, body.projectSlug);
    const attachments = [];
    if (body.attachments != null) {
      if (!Array.isArray(body.attachments) || body.attachments.length > 100) return { error: "Invalid attachments" };
      for (const a of body.attachments) {
        if (typeof a !== "string" || /[\r\n\0]/.test(a)) return { error: "Invalid attachment path" };
        const resolved = path.resolve(a);
        if (!isInside(resolved, c.uploadsDir) && !isInside(resolved, cwd))
          return { error: `Attachment must be under ${c.uploadsDir} or the project dir: ${a}` };
        attachments.push(resolved);
      }
    }
    if (!body.prompt.trim() && !attachments.length) return { error: "Empty prompt" };

    return {
      opts: {
        runId, prompt: body.prompt, projectSlug: body.projectSlug, cwd, sessionId, model, mode, thinking,
        effort, attachments, appendSystemPrompt, maxTurns, previewPort, authToken, autocompactTokens, agents, agent,
        fullPrompt: buildPrompt(body.prompt, attachments),
      },
    };
  }

  get(runId) {
    return this.runs.get(runId) || null;
  }

  create(opts) {
    if (this.runs.has(opts.runId)) {
      const err = new Error(`Run ${opts.runId} already exists`);
      err.code = "RUN_EXISTS";
      throw err;
    }
    fs.mkdirSync(opts.cwd, { recursive: true });
    const run = {
      runId: opts.runId,
      projectSlug: opts.projectSlug,
      cwd: opts.cwd,
      mode: opts.mode,
      model: opts.model,
      opts,
      status: "queued",
      createdAt: Date.now(),
      startedAt: null,
      endedAt: null,
      exitCode: null,
      sessionId: opts.sessionId || null,
      events: [],
      nextSeq: 1,
      subscribers: new Set(),
      proc: null,
      pid: null,
      aborted: false,
      stderrTail: "",
      finished: false,
    };
    this.runs.set(run.runId, run);
    this.queue.push(run);
    this.config.log("info", "run queued", { runId: run.runId, projectSlug: run.projectSlug, mode: run.mode, model: run.model });
    this._pump();
    return run;
  }

  _pump() {
    while (this.running < this.config.maxConcurrent && this.queue.length) {
      const run = this.queue.shift();
      if (run.status !== "queued") continue;
      this._start(run);
    }
  }

  _push(run, type, data) {
    if (type === "__internal_error") {
      this.config.log("warn", "normalizer error", { runId: run.runId, ...data });
      return;
    }
    if (type === "init" && data.sessionId) run.sessionId = data.sessionId;
    if (type === "result" && data.sessionId) run.sessionId = data.sessionId;
    const ev = { seq: run.nextSeq++, type, data };
    run.events.push(ev);
    const max = this.config.maxEventsPerRun;
    if (run.events.length > max * 1.1) run.events.splice(0, run.events.length - max);

import fs from 'node:fs';
import path from 'node:path';
import type { FastifyBaseLogger } from 'fastify';
import type { Dispatcher } from 'undici';
import type { Claudebox, V2RunBody } from './claudebox.js';
import type { Config } from './config.js';
import type { DB } from './db.js';
import { now, parseJson } from './db.js';
import type { Hub } from './hub.js';
import { SseParser, type SseMessage } from './lib/sse.js';
import { finalContent, parseSuggestions, visibleText } from './lib/suggestions.js';
import type { ProjectRow } from './auth.js';
import type { RunEventType, RunStatus, Suggestion, Usage } from './shared/protocol.js';
import type { Settings } from './settings.js';

const KNOWN_TYPES = new Set<RunEventType>([
  'init', 'thinking', 'text', 'block_end', 'tool_use', 'tool_result', 'todo', 'usage', 'compact', 'rate_limit', 'result', 'error', 'done',
]);
const PULSE: Partial<Record<RunEventType, number>> = {
  init: 1, compact: 0.6, text: 0.35, thinking: 0.25, tool_use: 0.85, tool_result: 0.55, todo: 0.5, result: 1, done: 0.8, error: 1,
};
const FLUSH_MS = 100;
const MAX_REATTACH = 6;
const ABORT_GRACE_MS = 10_000;
export const AUTH_HINT = 'Claude auth not configured/invalid — set the token in Admin → Settings.';

export interface StoredEvent {
  seq: number;
  type: string;
  data: unknown;
  /** epoch ms when the event was received */
  ts: number;
}

interface ActiveRun {
  id: string;
  conversationId: string;
  projectId: string;
  userId: string | null;
  assistantMessageId: string;
  body: V2RunBody | null; // null for recovered runs (reattach only)
  seq: number;
  upstreamSeq: number;
  pending: StoredEvent[];
  fullText: string;
  emittedLen: number;
  needSep: boolean;
  usage: Usage;
  costUsd: number;
  sessionCostUsd: number | null;
  durationMs: number | null;
  sawResult: boolean;
  resultIsError: boolean;
  resultText: string;
  sawError: boolean;
  lastError: string | null;
  exitCode: number | null | undefined;
  abortRequested: boolean;
  ended: boolean;
  controller: AbortController;
  startedAt: number;
  kind: 'compact' | null;
}

export function buildSystemPrompt(project: ProjectRow, cfg: Config, agents: { slug: string; description: string }[] = []): string {
  const cwd = `${cfg.claudeboxProjectsDir}/${project.slug}`;
  const base = `/preview/${project.slug}/`;
  const lines = [
    `You are working inside the Nxeon Workspace on the project "${project.name}".`,
    project.description ? `Project description: ${project.description}` : '',
    `Project directory (your cwd): ${cwd}. Keep all work inside this directory.`,
    `Assigned preview port: ${project.preview_port}. When you start a dev/preview server, bind it to 0.0.0.0 and use exactly this port (set PORT=${project.preview_port} HOST=0.0.0.0).`,
    project.preview_strip
      ? `The preview is shown to the user at ${cfg.publicUrl}${base} (the proxy strips this prefix, so the app can be served from /).`
      : `The preview is shown to the user at ${cfg.publicUrl}${base}. Configure the app's base path to "${base}" (e.g. Vite \`base: '${base}'\`, Next.js \`basePath: '${base.replace(/\/$/, '')}'\`), and make asset/HMR URLs relative to it. The env var BASE_PATH=${base} is set for preview servers.`,
    `Run long-lived servers in the background (e.g. with nohup ... &) so your turn can finish; the user's preview pane connects to the port.`,
    '',
    'TOKEN BUDGET — be economical; the user pays per token:',
    '- Pick the simplest approach that fully satisfies the request. Simple sites/pages: plain index.html + CSS/JS, no framework, no npm, no build step, unless the user asks for one or it is clearly required.',
    '- The workspace previews projects automatically (static files are served as-is; package.json dev servers are started for the user). Do NOT start servers, curl the preview, take screenshots, or look for browser tooling unless the user explicitly asks.',
    '- Use as few tool calls as possible: read only files you need, do not re-read files you just wrote, prefer one Write over many Edits for new files, skip exploratory commands, no subagents for small tasks.',
    '- Do not run builds, tests or type-checks for trivial changes unless asked.',
    '- Keep the final reply short: a few lines on what changed. No long recaps, tables, or repeating code the user can see in the editor.',
    `You have internet access (npm, pip, git, web).`,
    `Keep a concise, up-to-date README.md in the project root describing what the project is and how to run it.`,
    `Uploaded attachments are available read-only under ${cfg.claudeboxUploadsDir}/.`,
    ...(agents.length
      ? [
          '',
          'SUBAGENTS available via the Agent tool (subagent_type = name):',
          ...agents.map((a) => `- ${a.slug}: ${a.description.replace(/\s+/g, ' ').slice(0, 300)}`),
          'Delegate to a subagent only when it clearly saves effort (parallel research, independent review, large isolated tasks); do small tasks yourself.',
          'Exception: when the user writes @<name> (e.g. @researcher), delegate that part to exactly that subagent (subagent_type "<name>"), even for small tasks.',
        ]
      : []),
    '',
    'At the very end of EVERY final reply, append 2-3 short actionable follow-up suggestions for the user in exactly this format (valid JSON array on one line, no code fences):',
    '<nx-suggestions>[{"label":"Short button text","prompt":"The full prompt to send if clicked","kind":"next"}]</nx-suggestions>',
    'kind must be one of: next, fix, test, deploy, explain. The block is hidden from the user and rendered as clickable chips. Never mention it.',
  ];
  return lines.filter((l) => l !== '').join('\n');
}

export class RunManager {
  private active = new Map<string, ActiveRun>();
  private flushTimer: NodeJS.Timeout | null = null;
  private lastPulse = new Map<string, number>();
  private insertEvent;
  private updateRunTotals;

  constructor(
    private db: DB,
    private hub: Hub,
    private cb: Claudebox,
    private cfg: Config,
    private settings: Settings,
    private log: FastifyBaseLogger,
  ) {
    this.insertEvent = db.prepare(`INSERT OR IGNORE INTO run_events(run_id, seq, type, data, ts) VALUES (?,?,?,?,?)`);
    this.updateRunTotals = db.prepare(
      `UPDATE runs SET input_tokens=?, output_tokens=?, cache_read=?, cache_write=?, cost_usd=?, upstream_seq=? WHERE id=?`,
    );
  }

  isActive(runId: string) {
    return this.active.has(runId);
  }
  activeIds() {
    return [...this.active.keys()];
  }
  activeForConversation(conversationId: string): string | null {
    for (const r of this.active.values()) if (r.conversationId === conversationId) return r.id;
    return null;
  }

  /** Events from DB + in-memory pending, seq >= fromSeq. Synchronous so the caller can subscribe without gaps. */
  replay(runId: string, fromSeq: number): StoredEvent[] {
    const rows = this.db
      .prepare(`SELECT seq, type, data, ts FROM run_events WHERE run_id = ? AND seq >= ? ORDER BY seq`)
      .all(runId, fromSeq) as { seq: number; type: string; data: string; ts: number }[];
    const out: StoredEvent[] = rows.map((r) => ({ seq: r.seq, type: r.type, data: parseJson(r.data, null), ts: r.ts }));
    const a = this.active.get(runId);
    if (a) {
      const maxDb = out.length ? out[out.length - 1]!.seq : fromSeq - 1;
      for (const e of a.pending) if (e.seq > maxDb && e.seq >= fromSeq) out.push(e);
    }
    return out;
  }

  // ---------------- lifecycle ----------------

  start(p: {
    runId: string;
    conversationId: string;
    projectId: string;
    userId: string;
    assistantMessageId: string;
    body: V2RunBody;
    kind?: 'compact' | null;
  }) {
    const run = this.newState(p.runId, p.conversationId, p.projectId, p.userId, p.assistantMessageId, p.body);
    run.kind = p.kind ?? null;
    this.active.set(run.id, run);
    void this.drive(run, false);
  }

  private newState(
    id: string,
    conversationId: string,
    projectId: string,
    userId: string | null,
    assistantMessageId: string,
    body: V2RunBody | null,
  ): ActiveRun {
    return {
      id, conversationId, projectId, userId, assistantMessageId, body,
      seq: 0, upstreamSeq: 0, pending: [], fullText: '', emittedLen: 0, needSep: false,
      usage: { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 },
      costUsd: 0, sessionCostUsd: null, durationMs: null, sawResult: false, resultIsError: false, resultText: '', sawError: false,
      lastError: null, exitCode: undefined, abortRequested: false, ended: false, controller: new AbortController(),
      startedAt: now(),
      kind: null,
    };
  }

